{"hypotheses":[{"nl":"Split at the 5 separator and output 2 exactly where both corresponding cells in the left and right 3x3 panels are 1 (intersection).","code":"def transform(grid):
    h=len(grid); w=len(grid[0]); k=w//2
    return [[2 if grid[r][c]==1 and grid[r][c+k+1]==1 else 0 for c in range(k)] for r in range(h)]"},{"nl":"Output the left panel, recolored 1 to 2, but only retaining cells whose mirrored/right counterpart is nonzero.","code":"def transform(grid):
    return [[2 if grid[r][c]==1 and grid[r][-c-1]==1 else 0 for c in range(3)] for r in range(3)]"},{"nl":"Cellwise AND of the two panels, treating any nonzero value as true, colored 2.","code":"def transform(grid):
    return [[2 if grid[r][c]!=0 and grid[r][c+4]!=0 else 0 for c in range(3)] for r in range(3)]"},{"nl":"Keep left-panel 1s that have a right-panel 1 in the same row and column; all else zero.","code":"def transform(grid):
    return [[2*(grid[r][c]==1 and grid[r][c+4]==1) for c in range(3)] for r in range(3)]"},{"nl":"For each position, emit 2 when the two separated panels agree on value 1, otherwise emit 0.","code":"def transform(grid):
    return [[2 if grid[r][c]==grid[r][c+4]==1 else 0 for c in range(3)] for r in range(3)]"},{"nl":"Take the overlap of the two 3x3 binary shapes without reflection and recolor the overlap to 2.","code":"def transform(grid):
    a=[row[:3] for row in grid]; b=[row[4:7] for row in grid]
    return [[2 if a[r][c]&b[r][c] else 0 for c in range(3)] for r in range(3)]"},{"nl":"Output positions occupied in both halves, ignoring the separator column, using 2 for occupied intersections.","code":"def transform(grid):
    return [[2 if grid[r][c] and grid[r][c+4] else 0 for c in range(3)] for r in range(3)]"},{"nl":"Project the common 1-cells of the left and right objects onto a 3x3 output.","code":"def transform(grid):
    return [[2 if min(grid[r][c],grid[r][c+4])==1 else 0 for c in range(3)] for r in range(3)]"},{"nl":"Output the logical conjunction of aligned columns on either side of the central 5 divider.","code":"def transform(grid):
    return [[2 if (grid[r][c]==1 and grid[r][c+4]==1) else 0 for c in range(3)] for r in range(3)]"},{"nl":"The result is the left shape colored 2 with every cell absent from the right shape removed.","code":"def transform(grid):
    left=[row[:3] for row in grid]; right=[row[4:] for row in grid]
    return [[2 if left[r][c]==1 and right[r][c]==1 else 0 for c in range(3)] for r in range(3)]"}]}

